            'X-Organization-Id' =&gt; 'ID tổ chức cần làm việc (bắt buộc với endpoint yêu cầu auth). Example: 1',
            'Content-Type' =&gt; 'multipart/form-data',
            'Accept' =&gt; 'application/json',
