<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/documents"
);

const params = {
    "search": "architecto",
    "status": "architecto",
    "from_date": "2026-01-01",
    "to_date": "2026-12-31",
    "sort_by": "architecto",
    "sort_order": "architecto",
    "limit": "16",
    "document_type_id": "16",
    "document_field_id": "16",
    "issuing_agency_id": "16",
    "issuing_level_id": "16",
    "signer_id": "16",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Authorization": "Bearer Bearer {YOUR_ACCESS_TOKEN}",
    "X-Organization-Id": "ID tổ chức cần làm việc (bắt buộc với endpoint yêu cầu auth). Example: 1",
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
    method: "GET",
    headers,
}).then(response =&gt; response.json());</code></pre></div>


<div class="php-example">
    <pre><code class="language-php">$client = new \GuzzleHttp\Client();
